  1317→  public static updateRoom = async (
  1318→    roomId: string,
  1319→    displayName?: string,
  1320→    topic?: string,
  1321→    avatar?: Asset | null,
  1322→  ) => {
  1323→    if (!this.instance) throw new Error("Client not initialized");
  1324→    const room = this.instance.getRoom(roomId);
  1325→
  1326→    if (!room) throw new Error("Room not found");
  1327→
  1328→    if (displayName) await room.setName(displayName);
  1329→
  1330→    if (topic) await room.setTopic(topic);
  1331→
  1332→    if (avatar === null) {
  1333→      await room.removeAvatar();
  1334→    } else if (avatar?.base64) {
  1335→      const bytes = Buffer.from(avatar.base64, "base64");
  1336→      const mimeType = avatar.type ?? "image/jpeg";
  1337→
  1338→      await room.uploadAvatar(mimeType, bytes.buffer, {
  1339→        height: BigInt(32),
  1340→        width: BigInt(32),
  1341→        mimetype: mimeType,
  1342→        size: BigInt(avatar.fileSize ?? 0),
  1343→        thumbnailInfo: {
  1344→          height: BigInt(32),
  1345→          width: BigInt(32),
  1346→          mimetype: mimeType,
  1347→          size: BigInt(avatar.fileSize ?? 0),
  1348→        },
  1349→        thumbnailSource: undefined,
  1350→        blurhash: "",
  1351→        isAnimated: false,
  1352→      });
  1353→    }
  1354→  };
  1355→
  1356→  public static leaveRoom = async (roomId: string) => {
  1357→    if (!this.instance) throw new Error("Client not initialized");
  1358→    const room = this.instance.getRoom(roomId);
  1359→    if (!room) throw new Error("Room not found");
  1360→    await room.leave();
  1361→    const updatedRoom = this.instance.getRoom(roomId);
  1362→    if (!updatedRoom) throw new Error("Room not found");
  1363→    await updatedRoom.forget();
  1364→    // Manually refresh the room list to update UI immediately
  1365→    await this.refreshRoomList();
  1366→  };

