    33→    room?.displayName(),
    34→  );
    35→  const [topic, setTopic] = useState<string | undefined>(room?.topic());
    36→  const [isSaving, setIsSaving] = useState(false);
    37→  const [shouldRemoveAvatar, setShouldRemoveAvatar] = useState(false);
    38→  const [isDirect, setIsDirect] = useState(false);
    39→  const [userPowerLevel, setUserPowerLevel] = useState(0);
