    41→  const [avatarLevel, setAvatarLevel] = useState(50);
    42→  const [topicLevel, setTopicLevel] = useState(50);
    43→  const canEditName = userPowerLevel >= nameLevel;
    44→  const canEditAvatar = userPowerLevel >= avatarLevel;
    45→  const canEditTopic = userPowerLevel >= topicLevel;
