    47→  const isRemoveDisabled = () => {
    48→    if (isSaving || isDirect) return true;
    49→
    50→    if (selectedAsset) return false;
    51→
    52→    if (room.heroes()[0]?.avatarUrl || room.avatarUrl()) return false;
    53→
    54→    return true;
    55→  };
    56→
    57→  useEffect(() => {
    58→    room.isDirect().then(setIsDirect).catch(console.error);
    59→    MatrixService.getUserPowerLevel(room.id())
    60→      .then((level) => setUserPowerLevel(level ?? 0))
    61→      .catch(console.error);
