    59→export const RoomPermissions: React.FC<
    60→  NativeStackScreenProps<Routes, "roomPermissions">
    61→> = ({ navigation, route }) => {
    62→  const { room, userPowerLevel } = route.params;
    63→
    64→  const [currentValues, setCurrentValues] = useState<
    65→    Partial<Record<PermissionKey, number>>
    66→  >({});
    67→  const [pendingValues, setPendingValues] = useState<
    68→    Partial<Record<PermissionKey, number>>
    69→  >({});
    70→  const [activeKey, setActiveKey] = useState<PermissionKey | null>(null);
    71→  const [showValueModal, setShowValueModal] = useState(false);
    72→  const [showResetConfirm, setShowResetConfirm] = useState(false);
    73→  const [isLoading, setIsLoading] = useState(true);
    74→  const [isSaving, setIsSaving] = useState(false);
    75→  const [isResetting, setIsResetting] = useState(false);
    76→
    77→  const hasChanges = Object.keys(pendingValues).length > 0;
    78→
    79→  const getDefaultLevel = (key: PermissionKey): number => {
    80→    for (const section of SECTIONS) {
    81→      for (const item of section.items) {
    82→        if (item.key === key) return item.defaultLevel;
    83→      }
    84→    }
    85→    return 0;
    86→  };
    87→
    88→  const getDisplayLevel = (key: PermissionKey) => {
    89→    if (key in pendingValues) return pendingValues[key]!;
    90→    if (key in currentValues) return currentValues[key]!;
    91→    return getDefaultLevel(key);
    92→  };
    93→
    94→  const handleSave = async () => {
    95→    setIsSaving(true);
    96→    try {
    97→      const changes: RoomPowerLevelChanges = {
    98→        ban: undefined,
    99→        invite: undefined,
   100→        kick: undefined,
   101→        redact: undefined,
   102→        eventsDefault: undefined,
   103→        stateDefault: undefined,
   104→        usersDefault: undefined,
   105→        roomName: undefined,
   106→        roomAvatar: undefined,
   107→        roomTopic: undefined,
   108→        spaceChild: undefined,
   109→      };
   110→      for (const [key, value] of Object.entries(pendingValues)) {
   111→        (changes as Record<string, bigint | undefined>)[key] = BigInt(
   112→          value as number,
   113→        );
   114→      }
   115→      await MatrixService.applyRoomPowerLevelChanges(room.id(), changes);
   116→      navigation.goBack();
