   120→      setIsSaving(false);
   121→    }
   122→  };
   123→
   124→  const handleReset = async () => {
   125→    setIsResetting(true);
   126→    try {
   127→      await MatrixService.resetRoomPowerLevels(room.id());
   128→      setShowResetConfirm(false);
   129→      navigation.goBack();
   130→    } catch (error) {
   131→      console.error("Failed to reset permissions:", error);
   132→    } finally {
   133→      setIsResetting(false);
   134→    }
   135→  };
   136→
   137→  const handleSelectLevel = (level: number) => {
   138→    if (!activeKey) return;
   139→    setPendingValues((prev) => ({ ...prev, [activeKey]: level }));
   140→    setShowValueModal(false);
   141→  };
   142→
   143→  useEffect(() => {
   144→    MatrixService.getRoomPowerLevels(room.id())
   145→      .then((pl) => {
   146→        if (!pl) return;
   147→        const vals = pl.values();
   148→        setCurrentValues({
   149→          invite: Number(vals.invite),
   150→          kick: Number(vals.kick),
   151→          ban: Number(vals.ban),
   152→          roomName: Number(vals.roomName),
   153→          roomAvatar: Number(vals.roomAvatar),
   154→          roomTopic: Number(vals.roomTopic),
   155→          eventsDefault: Number(vals.eventsDefault),
   156→          redact: Number(vals.redact),
   157→        });
   158→      })
   159→      .catch(console.error)
   160→      .finally(() => setIsLoading(false));
   161→  }, [room]);
   162→
   163→  const availableLevels = useMemo(() => {
   164→    const levels = [0, 50];
   165→    if (userPowerLevel >= 100) levels.push(100);
   166→    return levels;
   167→  }, [userPowerLevel]);
   168→
   169→  if (isLoading) return <Loading />;
   170→
   171→  return (
   172→    <ScreenLayout>
   173→      {(isSaving || isResetting) && (
   174→        <Loading text={isSaving ? "Saving..." : "Resetting..."} />
   175→      )}
   176→      <Block flex={1} scrollable>
   177→        <GoBackHeader
   178→          title="Permissions"
   179→          margins={{ marginBottom: 24 }}
   180→          rightComp={
