   183→                <Text color={Colors.primary}>Save</Text>
   184→              </Button.Wrapper>
   185→            )
   186→          }
   187→        />
   188→
   189→        {SECTIONS.map((section) => (
   190→          <Block key={section.title} margins={{ marginBottom: 20 }}>
   191→            <Text
   192→              size={TextSize.small}
   193→              color={Colors.white50}
   194→              margins={{ marginBottom: 8, marginLeft: 4 }}
   195→            >
   196→              {section.title}
   197→            </Text>
   198→            <Block
   199→              border={{ borderRadius: 16 }}
   200→              width="100%"
   201→              background={Colors.white5}
   202→            >
   203→              {section.items.map((item, index) => {
   204→                const isLast = index === section.items.length - 1;
   205→                const displayLevel = getDisplayLevel(item.key);
   206→                const isItemDisabled =
   207→                  userPowerLevel < 100 && displayLevel >= 100;
   208→
   209→                return (
   210→                  <Button.Wrapper
   211→                    key={item.key}
   212→                    disabled={isItemDisabled}
   213→                    onPress={() => {
   214→                      setActiveKey(item.key);
   215→                      setShowValueModal(true);
   216→                    }}
   217→                  >
   218→                    <Block
   219→                      paddings={[0, 12]}
   220→                      opacity={isItemDisabled ? 0.5 : 1}
   221→                    >
   222→                      <Block
   223→                        flexDirection="row"
   224→                        align="center"
   225→                        gap={12}
   226→                        paddings={[20, 0]}
   227→                        border={
   228→                          !isLast
   229→                            ? {
   230→                                borderBottomWidth: 1,
   231→                                borderColor: Colors.white5,
   232→                              }
   233→                            : undefined
   234→                        }
   235→                      >
   236→                        <Text flex={1}>{item.label}</Text>
   237→                        <Text color={Colors.white50}>
   238→                          {getLevelLabel(displayLevel)}
   239→                        </Text>
   240→                        <Image
   241→                          source={require("assets/icons/caret-left.png")}
   242→                          style={styles.caret}
   243→                          tintColor={Colors.white50}
   244→                        />
   245→                      </Block>
   246→                    </Block>
   247→                  </Button.Wrapper>
   248→                );
   249→              })}
   250→            </Block>
   251→          </Block>
   252→        ))}
   253→
   254→        <Block>
   255→          <Button.Warning
